# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::ReservationAccess do
  # "An anonymous or user-delegated request never gets it."
  it "refuses a user token of every role even for its own company" do
    %w[owner admin employee].each do |role|
      user = Timekeeping::Identity.new(kind: :user, status: :verified, user_id: 7, company_id: 1, role:)

      expect([role, described_class.decide(identity: user, company_id: 1, operation: "reservations.prepare")])
        .to eq([role, :forbidden])
    end
    expect(described_class.decide(identity: Timekeeping::Identity.anonymous(:missing), company_id: 1,
                                  operation: "reservations.prepare")).to eq(:unauthorized)
  end
end

RSpec.describe Timekeeping::ReservationAccess do
  # "The background credential (`TIMEKEEPING_SERVICE_TOKEN`) is bound to one `company_id` per request and
  # allowed only these operations: `reservations.prepare`, `reservations.commit`, `reservations.abort`,
  # `invoices.mark_billed`, `entries.import`, `agents.detach_entries`."
  it "binds a signed service token to its company and its named operations" do
    secret = "reservation-access-secret-#{SecureRandom.hex(16)}"
    resolve = lambda do |company_id, operations|
      now = Time.now.to_i
      token = JWT.encode({ typ: "timekeeping_service", sub: "invoice-boundary", company_id:, operations:,
                           iat: now, exp: now + 60, jti: SecureRandom.uuid }, rsa_key_pair, "RS256")
      Timekeeping::Identity.resolve(authorization: "Bearer #{token}", public_key: rsa_key_pair.public_key.to_pem,
                                    service_token: secret)
    end
    resolve_bearer = lambda do |bearer|
      Timekeeping::Identity.resolve(authorization: bearer && "Bearer #{bearer}",
                                    public_key: rsa_key_pair.public_key.to_pem, service_token: secret)
    end
    decide = ->(identity, company_id, operation) { described_class.decide(identity:, company_id:, operation:) }

    bound = resolve.call(1, ["reservations.prepare"])
    expect(decide.call(bound, 1, "reservations.prepare")).to eq(:allowed)
    expect(decide.call(bound, 1, "reservations.commit")).to eq(:forbidden)
    expect(decide.call(bound, 2, "reservations.prepare")).to eq(:not_found)
    # A name outside the background allowlist grants nothing, even when the token lists it.
    wide = resolve.call(1, ["prepare", "admin.everything"])
    expect(decide.call(wide, 1, "prepare")).not_to eq(:allowed)
    # Listing a non-background operation beside an allowed one neither grants it nor cancels the allowed one.
    mixed = resolve.call(1, ["reservations.prepare", "entries.delete"])
    expect(decide.call(mixed, 1, "reservations.prepare")).to eq(:allowed)
    expect(decide.call(mixed, 2, "reservations.prepare")).to eq(:not_found)
    expect(decide.call(mixed, 1, "reservations.commit")).to eq(:forbidden)
    expect(decide.call(mixed, 1, "entries.delete")).to eq(:forbidden)
    # "An anonymous or user-delegated request never gets it."
    owner = resolve_bearer.call(mint_token({ sub: 7, company_id: 1, role: "owner" }))
    expect(decide.call(owner, 1, "reservations.prepare")).to eq(:forbidden)
    expect(decide.call(resolve_bearer.call(nil), 1, "reservations.prepare")).to eq(:unauthorized)
    # The shared token itself carries no company, so it never reaches these routes.
    expect(decide.call(resolve_bearer.call(secret), 1, "reservations.prepare")).to eq(:forbidden)
  end
end

RSpec.describe Timekeeping::ReservationAccess, "for signed service tokens" do
  def bound_service_for_access(operations:, company_id: 1)
    Timekeeping::Identity.new(kind: :service, status: :verified, user_id: nil, company_id:, role: nil,
                              service_name: "invoice-boundary", operations:)
  end

  it "refuses an expired service token as unauthorized" do
    expect(described_class.decide(identity: Timekeeping::Identity.anonymous(:expired), company_id: 1,
                                  operation: "reservations.commit")).to eq(:unauthorized)
  end

  it "forbids a token that lists no operation" do
    expect(described_class.decide(identity: bound_service_for_access(operations: []), company_id: 1,
                                  operation: "reservations.prepare")).to eq(:forbidden)
  end

  it "forbids before it compares companies, so an unlisted operation never reveals a company" do
    identity = bound_service_for_access(operations: ["reservations.prepare"])

    expect(described_class.decide(identity:, company_id: 2, operation: "reservations.abort")).to eq(:forbidden)
  end

  it "freezes its rules and every rule row, and the command tables' nested rules" do
    expect(described_class::RULES).to be_frozen.and(all(be_frozen))
    expect(Timekeeping::ServiceCommands::COMMANDS.values).to all(be_frozen)
    expect(Timekeeping::ServiceCommands::COMMANDS.values.map { |command| command.fetch(:changes) }).to all(be_frozen)
    expect(Timekeeping::ReservationOperations::TERMINAL_ANSWERS.values).to all(be_frozen)
    expect(Timekeeping::ReservationRequest::ROUTES.values).to all(be_frozen)
    expect(Timekeeping::ReservationRequest::ROUTES.values.map { |route| route.fetch(:fields) }).to all(be_frozen)
  end

  it "maps every route to a background operation" do
    expect(described_class::ROUTE_OPERATIONS.values - TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS).to eq([])
  end

  it "allows each route for a token that lists its operation" do
    described_class::ROUTE_OPERATIONS.each_value do |operation|
      identity = bound_service_for_access(operations: [operation])

      expect([operation, described_class.decide(identity:, company_id: "1", operation:)]).to eq([operation, :allowed])
    end
  end
end
